using ReeLib;using System.Text.Json;using System.Collections;using System.Globalization;
var root="E:/CodexPepo/RE_Research";Directory.SetCurrentDirectory(root);ResourceRepository.LocalResourceRepositoryFolder=root+"/references/reelib-cache";ResourceRepository.DisableOnlineUpdater=true;
var parser=new RszParser("references/RE4/rszre4_reasy.json");parser.ReadPatch("references/RE4/rsz_patch.json");var option=new RszFileOption(GameName.re4,parser);
var output="reports/RE4";var source=output+"/extracted";var jo=new JsonSerializerOptions{IncludeFields=true,NumberHandling=System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals};
object? Val(object? x,int depth=0){if(x is null)return null;if(x is RszInstance i){if(depth>0)return new{Ref=i.Index,Class=i.RszClass.name};var fields=new Dictionary<string,object?>();for(int k=0;k<i.Values.Length;k++)fields[i.Fields[k].name]=Val(i.Values[k],depth+1);return new{Index=i.Index,Class=i.RszClass.name,Userdata=i.RSZUserData?.Path,Fields=fields};}if(x is string||x.GetType().IsPrimitive||x is decimal)return x;if(x is IEnumerable a)return a.Cast<object?>().Select(v=>Val(v,depth)).ToArray();return x.ToString();}
string Csv(object? v)=>"\""+(Convert.ToString(v,CultureInfo.InvariantCulture)??"").Replace("\"","\"\"")+"\"";
var mode=args.FirstOrDefault()??"all";var limit=args.Length>1?int.Parse(args[1]):int.MaxValue;
using var logs=new StreamWriter(output+"/parse_log_"+mode+".jsonl");using var motions=new StreamWriter(output+"/motions_"+mode+".csv");motions.WriteLine("path,slot,id,switch,kind,name,frames,fps,seconds,tracks,base_path");
int n=0,ok=0;var files=Directory.EnumerateFiles(source,"*",SearchOption.AllDirectories).Where(f=> mode=="animation"?f.Contains(".motlist.")||f.Contains(".motbank."):f.Contains(".user.")||f.Contains(".pfb.")||f.Contains(".scn.")||f.Contains(".motfsm2."));
if(mode=="fsm")files=files.Where(f=>f.Contains(".motfsm2."));
foreach(var file in files.Take(limit)){var path=Path.GetRelativePath(source,file).Replace('\\','/');try{object data;
if(path.Contains(".motlist.")){using var f=new MotlistFile(new FileHandler(file));if(!f.Read())throw new Exception("Read false");var entries=new List<object>();int slot=0;foreach(var m in f.Motions){string kind=m.MotFile?.GetType().Name??"empty";if(m.MotFile is MotFile mot){motions.WriteLine(string.Join(",",new object?[]{path,slot,m.motNumber,m.Switch,kind,mot.Header.motName,mot.Header.frameCount,mot.Header.FrameRate,mot.Header.FrameRate>0?mot.Header.frameCount/mot.Header.FrameRate:null,mot.BoneClips.Count,f.Header.BaseMotListPath}.Select(Csv)));entries.Add(new{Slot=slot,ID=m.motNumber,m.Switch,Kind=kind,Name=mot.Header.motName,Frames=mot.Header.frameCount,FPS=mot.Header.FrameRate,Tracks=mot.BoneClips.Count});}else if(m.MotFile is MotTreeFile t){entries.Add(new{Slot=slot,ID=m.motNumber,m.Switch,Kind=kind,t.Name,Nodes=t.Nodes.Select((nd,i)=>new{Index=i,nd.name,Type=nd.TypeInfo?.classShortname,Parameters=nd.Parameters.Select(p=>new{p.name,p.type,p.hash,Value=Val(p.value)}).ToArray()}).ToArray(),Links=t.Links.Select(l=>new{l.inputNodeIndex,l.inputPinNo,l.outputNodeIndex,l.outputPinNo,l.type}).ToArray()});}else entries.Add(new{Slot=slot,ID=m.motNumber,m.Switch,Kind=kind});slot++;}data=new{Path=path,f.Header.MotListName,f.Header.BaseMotListPath,Entries=entries};}
else if(path.Contains(".motbank.")){using var f=new MotbankFile(new FileHandler(file));if(!f.Read())throw new Exception("Read false");data=new{Path=path,f.UvarPath,f.JmapPath,Entries=f.MotlistItems.Select(e=>new{e.BankID,e.BankType,e.Path})};}
else if(path.Contains(".motfsm2.")){using var f=new Motfsm2File(option,new FileHandler(file));if(!f.Read())throw new Exception("Read false");data=new{Path=path,SchemaMismatches=f.GetAllRSZFiles().SelectMany(r=>r.InstanceInfoList).Where(i=>parser.ClassDict.TryGetValue(i.typeId,out var cls)&&cls.crc!=i.CRC).Select(i=>new{Class=parser.ClassDict[i.typeId].name,FileCRC=i.CRC,SchemaCRC=parser.ClassDict[i.typeId].crc}).Distinct().ToArray(),RszSections=f.GetAllRSZFiles().Select((r,section)=>new{Section=section,Instances=r.InstanceList.Select(i=>Val(i)).ToArray()}).ToArray(),Nodes=f.BhvtFile.Nodes.Select(nd=>new{ID=nd.ID.ToString(),nd.Name,nd.FullName,Parent=nd.Parent?.FullName,ParentID=nd.Parent?.ID.ToString(),Actions=nd.Actions.Actions.Select(a=>Val(a.Instance)).ToArray(),Selector=Val(nd.Selector),EntryTransitions=nd.Transitions.Transitions.Select(t=>new{Target=t.StartNode?.FullName,TargetID=t.StartNode?.ID.ToString(),Condition=Val(t.Condition)}).ToArray(),AllStates=nd.AllStates.AllStates.Select(a=>new{Target=a.TargetNode?.FullName,TargetID=a.TargetNode?.ID.ToString(),Condition=Val(a.Condition),Transition=a.TransitionData}).ToArray(),Children=nd.Children.Children.Select(c=>new{Target=c.ChildNode?.FullName,TargetID=c.ChildNode?.ID.ToString(),Condition=Val(c.Condition)}).ToArray(),States=nd.States.States.Select(s=>new{Target=s.TargetNode?.FullName,TargetID=s.TargetNode?.ID.ToString(),Condition=Val(s.Condition),s.transitionMapID,Transition=s.TransitionData}).ToArray()}).ToArray()};}
else{using BaseRszFile f=path.Contains(".user.")?new UserFile(option,new FileHandler(file)):path.Contains(".pfb.")?new PfbFile(option,new FileHandler(file)):new ScnFile(option,new FileHandler(file));if(!f.Read())throw new Exception("Read false");var r=f.GetRSZ()!;data=new{Path=path,SchemaMismatches=r.InstanceInfoList.Where(i=>parser.ClassDict.TryGetValue(i.typeId,out var cls)&&cls.crc!=i.CRC).Select(i=>new{Class=parser.ClassDict[i.typeId].name,FileCRC=i.CRC,SchemaCRC=parser.ClassDict[i.typeId].crc}).Distinct().ToArray(),Objects=r.ObjectList.Select(i=>new{Ref=i.Index,Class=i.RszClass.name}).ToArray(),Instances=r.InstanceList.Select(i=>Val(i)).ToArray()};}
var dest=output+"/parsed/"+path+".json";Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.WriteAllText(dest,JsonSerializer.Serialize(data,jo));logs.WriteLine(JsonSerializer.Serialize(new{Path=path,Success=true}));ok++;
}catch(Exception ex){logs.WriteLine(JsonSerializer.Serialize(new{Path=path,Success=false,Error=ex.Message}));if(n<20)Console.WriteLine("FAIL "+path+": "+ex.Message);}n++;if(n%1000==0){logs.Flush();motions.Flush();Console.WriteLine($"{mode}: {n} / success {ok}");}}
Console.WriteLine($"DONE {mode}: {n} / success {ok}");

